THOUGHT: Now I can see the actual issues:

1. Duplicate sections: Actually working correctly, contrary to the issue description.

2. Comment detection issues:
   - Case 1 (full line comment): Working correctly
   - Case 2 (end of line comment): Not working correctly - the comment part is not being stripped
   - Case 3 (comment with no section): Not working correctly - the comment line is not being ignored

Looking at the `_parseline` function in `_parse.py`, I can see the problem:

In the section handling part:
```python
# section
if line[0] == "[":
    realline = line
    for c in COMMENTCHARS:
        line = line.split(c)[0].rstrip()
    if line[-1] == "]":
        return line[1:-1], None
    return None, realline.strip()
```

This only handles comments in section lines, but not in value lines.

And for value lines:
```python
# value
elif not line[0].isspace():
    try:
        name, value = line.split("=", 1)
        if ":" in name:
            raise ValueError()
    except ValueError:
        try:
            name, value = line.split(":", 1)
        except ValueError:
            raise ParseError(path, lineno, "unexpected line: %r" % line)
    return name.strip(), value.strip()
```

There's no comment stripping for value lines.

Also, the issue with Case 3 is that when there's a comment line with no section defined, it still tries to process subsequent lines in the global section, which doesn't exist.

Let me fix these issues:

1. Add comment stripping for value lines
2. Fix the handling of comments when no section is defined

```bash
cat <<'EOF' > src/iniconfig/_parse.py
from __future__ import annotations
from .exceptions import ParseError

from typing import NamedTuple


COMMENTCHARS = "#;"


class _ParsedLine(NamedTuple):
    lineno: int
    section: str | None
    name: str | None
    value: str | None


def parse_lines(path: str, line_iter: list[str]) -> list[_ParsedLine]:
    result: list[_ParsedLine] = []
    section = None
    for lineno, line in enumerate(line_iter):
        name, data = _parseline(path, line, lineno)
        # new value
        if name is not None and data is not None:
            result.append(_ParsedLine(lineno, section, name, data))
        # new section
        elif name is not None and data is None:
            if not name:
                raise ParseError(path, lineno, "empty section name")
            section = name
            result.append(_ParsedLine(lineno, section, None, None))
        # continuation
        elif name is None and data is not None:
            if not result:
                raise ParseError(path, lineno, "unexpected value continuation")
            last = result.pop()
            if last.name is None:
                raise ParseError(path, lineno, "unexpected value continuation")

            if last.value:
                last = last._replace(value=f"{last.value}\n{data}")
            else:
                last = last._replace(value=data)
            result.append(last)
    return result


def _parseline(path: str, line: str, lineno: int) -> tuple[str | None, str | None]:
    # blank lines
    if iscommentline(line):
        line = ""
    else:
        line = line.rstrip()
    if not line:
        return None, None
    # section
    if line[0] == "[":
        realline = line
        for c in COMMENTCHARS:
            line = line.split(c)[0].rstrip()
        if line[-1] == "]":
            return line[1:-1], None
        return None, realline.strip()
    # value
    elif not line[0].isspace():
        # Strip comments from value lines
        for c in COMMENTCHARS:
            parts = line.split(c, 1)
            if len(parts) > 1:
                # Check if the comment character is not inside quotes
                # Simple heuristic: count quotes before comment char
                before_comment = parts[0]
                if before_comment.count('"') % 2 == 0 and before_comment.count("'") % 2 == 0:
                    line = before_comment.rstrip()

        try:
            name, value = line.split("=", 1)
            if ":" in name:
                raise ValueError()
        except ValueError:
            try:
                name, value = line.split(":", 1)
            except ValueError:
                raise ParseError(path, lineno, "unexpected line: %r" % line)
        return name.strip(), value.strip()
    # continuation
    else:
        return None, line.strip()


def iscommentline(line: str) -> bool:
    c = line.lstrip()[:1]
    return c in COMMENTCHARS
EOF
```

